window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-af9f248e4e243a6e"]={"versions": [{"id": "FIG-af9f248e4e243a6e", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Konstanten und Wertebelegungen (<code>ValueSpecification</code>) im Metamodell des AUTOSAR-Software-Component-Templates (<code>AUTOSAR_SoftwareComponentTemplate</code>). Das Diagramm verortet die Modellierung von Festwerten in Relation zu <code>DataPrototype</code>, Datentypen (<code>Datatype</code>) und dem Wurzelelement <code>ConstantSpecification</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm modelliert folgende Klassen, Spezialisierungen und Relationen:</p>\n<ul class=\"fig-list\">\n<li><strong>Identifiable / ARElement:</strong></li>\n<li><code>DataPrototype</code> (Stereotyp <code>«atpPrototype»</code>, erbt von <code>Identifiable</code>) steht über die gerichtete Assoziation <code>«isOfType»</code> (<code>+type</code>: 1) in Beziehung zum Datentyp <code>Datatype</code> (Stereotyp <code>«atpType»</code>, erbt von <code>ARElement</code>); Kardinalität auf Prototypseite ist <code>0..*</code>.</li>\n<li><code>ConstantSpecification</code> erbt von <code>ARElement</code> und besitzt per Komposition genau eine Wertebelegung <code>+value: ValueSpecification [1]</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>ValueSpecification-Hierarchie:</strong></li>\n<li>Die abstrakte Basisklasse <code>ValueSpecification</code> spezialisiert <code>DataPrototype</code>.</li>\n<li>Direkte Spezialisierungen von <code>ValueSpecification</code>:</li>\n<li><code>ConstantReference</code>: Referenziert über eine gerichtete Assoziation <code>+constant: ConstantSpecification [1]</code> eine definierte Konstante.</li>\n<li><code>PrimitiveSpecification</code>: Abstrakte Basis für skalare Literalwerte.</li>\n<li><code>ArraySpecification</code>: Aggregiert/komponiert über <code>+element</code> geordnete Kind-Wertespezifikationen (<code>ValueSpecification [*] {ordered}</code>).</li>\n<li><code>RecordSpecification</code>: Komponiert über <code>+element</code> geordnete Kind-Wertespezifikationen (<code>ValueSpecification [*] {ordered}</code>).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>PrimitiveSpecification-Literale:</strong></li>\n<li><code>IntegerLiteral</code> mit Attribut <code>+ value: Int</code></li>\n<li><code>RealLiteral</code> mit Attribut <code>+ value: Float</code></li>\n<li><code>BooleanLiteral</code> mit Attribut <code>+ value: Boolean</code></li>\n<li><code>CharLiteral</code> mit Attribut <code>+ value: String</code></li>\n<li><code>StringLiteral</code> mit Attribut <code>+ value: String</code></li>\n<li><code>OpaqueLiteral</code> mit Attribut <code>+ value: String</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Zustandsübergänge. Die Baumstruktur von Datenwerten wird statisch durch rekursive Kompositionen (<code>ArraySpecification</code> und <code>RecordSpecification</code> referenzieren geordnete Listen von <code>ValueSpecification</code>) sowie Verweise auf <code>ConstantSpecification</code> abgebildet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Modellierung legt die verbindliche Struktur für AUTOSAR-XML-Beschreibungen (ARXML) von Festwerten fest:</p>\n<ul class=\"fig-list\">\n<li>Jeder <code>ConstantSpecification</code> muss exakt eine konkrete <code>ValueSpecification</code> zugewiesen sein.</li>\n<li>Zusammengesetzte Werte (Arrays, Records) werden strikt über geordnete (<code>{ordered}</code>) Kollektionen von <code>ValueSpecification</code>-Instanzen aufgebaut, was die Reihenfolge der Elemente in ARXML serialisiert.</li>\n<li>Werte sind typsicher über <code>DataPrototype</code> an das Metamodell typisiert (<code>«isOfType»</code> verweist auf <code>Datatype</code>).</li>\n<li>Primitive Literale müssen den spezifizierten Primitivtypen (<code>Int</code>, <code>Float</code>, <code>Boolean</code>, <code>String</code>) entsprechen.</li>\n</ul>"}, {"id": "FIG-06419ad8b951020e", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Konstanten und Wertebelegungen (<code>ValueSpecification</code>) im Metamodell des AUTOSAR-Software-Component-Templates (<code>AUTOSAR_SoftwareComponentTemplate</code>). Das Diagramm verortet die Modellierung von Festwerten in Relation zu <code>DataPrototype</code>, Datentypen (<code>Datatype</code>) und dem Wurzelelement <code>ConstantSpecification</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm modelliert folgende Klassen, Spezialisierungen und Relationen:</p>\n<ul class=\"fig-list\">\n<li><strong>Identifiable / ARElement:</strong></li>\n<li><code>DataPrototype</code> (Stereotyp <code>«atpPrototype»</code>, erbt von <code>Identifiable</code>) steht über die gerichtete Assoziation <code>«isOfType»</code> (<code>+type</code>: 1) in Beziehung zum Datentyp <code>Datatype</code> (Stereotyp <code>«atpType»</code>, erbt von <code>ARElement</code>); Kardinalität auf Prototypseite ist <code>0..*</code>.</li>\n<li><code>ConstantSpecification</code> erbt von <code>ARElement</code> und besitzt per Komposition genau eine Wertebelegung <code>+value: ValueSpecification [1]</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>ValueSpecification-Hierarchie:</strong></li>\n<li>Die abstrakte Basisklasse <code>ValueSpecification</code> spezialisiert <code>DataPrototype</code>.</li>\n<li>Direkte Spezialisierungen von <code>ValueSpecification</code>:</li>\n<li><code>ConstantReference</code>: Referenziert über eine gerichtete Assoziation <code>+constant: ConstantSpecification [1]</code> eine definierte Konstante.</li>\n<li><code>PrimitiveSpecification</code>: Abstrakte Basis für skalare Literalwerte.</li>\n<li><code>ArraySpecification</code>: Aggregiert/komponiert über <code>+element</code> geordnete Kind-Wertespezifikationen (<code>ValueSpecification [*] {ordered}</code>).</li>\n<li><code>RecordSpecification</code>: Komponiert über <code>+element</code> geordnete Kind-Wertespezifikationen (<code>ValueSpecification [*] {ordered}</code>).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>PrimitiveSpecification-Literale:</strong></li>\n<li><code>IntegerLiteral</code> mit Attribut <code>+ value: Int</code></li>\n<li><code>RealLiteral</code> mit Attribut <code>+ value: Float</code></li>\n<li><code>BooleanLiteral</code> mit Attribut <code>+ value: Boolean</code></li>\n<li><code>CharLiteral</code> mit Attribut <code>+ value: String</code></li>\n<li><code>StringLiteral</code> mit Attribut <code>+ value: String</code></li>\n<li><code>OpaqueLiteral</code> mit Attribut <code>+ value: String</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Zustandsübergänge. Die Baumstruktur von Datenwerten wird statisch durch rekursive Kompositionen (<code>ArraySpecification</code> und <code>RecordSpecification</code> referenzieren geordnete Listen von <code>ValueSpecification</code>) sowie Verweise auf <code>ConstantSpecification</code> abgebildet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Modellierung legt die verbindliche Struktur für AUTOSAR-XML-Beschreibungen (ARXML) von Festwerten fest:</p>\n<ul class=\"fig-list\">\n<li>Jeder <code>ConstantSpecification</code> muss exakt eine konkrete <code>ValueSpecification</code> zugewiesen sein.</li>\n<li>Zusammengesetzte Werte (Arrays, Records) werden strikt über geordnete (<code>{ordered}</code>) Kollektionen von <code>ValueSpecification</code>-Instanzen aufgebaut, was die Reihenfolge der Elemente in ARXML serialisiert.</li>\n<li>Werte sind typsicher über <code>DataPrototype</code> an das Metamodell typisiert (<code>«isOfType»</code> verweist auf <code>Datatype</code>).</li>\n<li>Primitive Literale müssen den spezifizierten Primitivtypen (<code>Int</code>, <code>Float</code>, <code>Boolean</code>, <code>String</code>) entsprechen.</li>\n</ul>"}, {"id": "FIG-cc08576c327ea3d9", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Konstanten und Wertebelegungen (<code>ValueSpecification</code>) im Metamodell des AUTOSAR-Software-Component-Templates (<code>AUTOSAR_SoftwareComponentTemplate</code>). Das Diagramm verortet die Modellierung von Festwerten in Relation zu <code>DataPrototype</code>, Datentypen (<code>Datatype</code>) und dem Wurzelelement <code>ConstantSpecification</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm modelliert folgende Klassen, Spezialisierungen und Relationen:</p>\n<ul class=\"fig-list\">\n<li><strong>Identifiable / ARElement:</strong></li>\n<li><code>DataPrototype</code> (Stereotyp <code>«atpPrototype»</code>, erbt von <code>Identifiable</code>) steht über die gerichtete Assoziation <code>«isOfType»</code> (<code>+type</code>: 1) in Beziehung zum Datentyp <code>Datatype</code> (Stereotyp <code>«atpType»</code>, erbt von <code>ARElement</code>); Kardinalität auf Prototypseite ist <code>0..*</code>.</li>\n<li><code>ConstantSpecification</code> erbt von <code>ARElement</code> und besitzt per Komposition genau eine Wertebelegung <code>+value: ValueSpecification [1]</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>ValueSpecification-Hierarchie:</strong></li>\n<li>Die abstrakte Basisklasse <code>ValueSpecification</code> spezialisiert <code>DataPrototype</code>.</li>\n<li>Direkte Spezialisierungen von <code>ValueSpecification</code>:</li>\n<li><code>ConstantReference</code>: Referenziert über eine gerichtete Assoziation <code>+constant: ConstantSpecification [1]</code> eine definierte Konstante.</li>\n<li><code>PrimitiveSpecification</code>: Abstrakte Basis für skalare Literalwerte.</li>\n<li><code>ArraySpecification</code>: Aggregiert/komponiert über <code>+element</code> geordnete Kind-Wertespezifikationen (<code>ValueSpecification [*] {ordered}</code>).</li>\n<li><code>RecordSpecification</code>: Komponiert über <code>+element</code> geordnete Kind-Wertespezifikationen (<code>ValueSpecification [*] {ordered}</code>).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>PrimitiveSpecification-Literale:</strong></li>\n<li><code>IntegerLiteral</code> mit Attribut <code>+ value :Integer</code></li>\n<li><code>RealLiteral</code> mit Attribut <code>+ value :Float</code></li>\n<li><code>BooleanLiteral</code> mit Attribut <code>+ value :Boolean</code></li>\n<li><code>CharLiteral</code> mit Attribut <code>+ value :String</code></li>\n<li><code>StringLiteral</code> mit Attribut <code>+ value :String</code></li>\n<li><code>OpaqueLiteral</code> mit Attribut <code>+ value :String</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Zustandsübergänge. Die Baumstruktur von Datenwerten wird statisch durch rekursive Kompositionen (<code>ArraySpecification</code> und <code>RecordSpecification</code> referenzieren geordnete Listen von <code>ValueSpecification</code>) sowie Verweise auf <code>ConstantSpecification</code> abgebildet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Modellierung legt die verbindliche Struktur für AUTOSAR-XML-Beschreibungen (ARXML) von Festwerten fest:</p>\n<ul class=\"fig-list\">\n<li>Jeder <code>ConstantSpecification</code> muss exakt eine konkrete <code>ValueSpecification</code> zugewiesen sein.</li>\n<li>Zusammengesetzte Werte (Arrays, Records) werden strikt über geordnete (<code>{ordered}</code>) Kollektionen von <code>ValueSpecification</code>-Instanzen aufgebaut, was die Reihenfolge der Elemente in ARXML serialisiert.</li>\n<li>Werte sind typsicher über <code>DataPrototype</code> an das Metamodell typisiert (<code>«isOfType»</code> verweist auf <code>Datatype</code>).</li>\n<li>Primitive Literale müssen den spezifizierten Primitivtypen entsprechen, wobei ganzzahlige Literale nun als <code>Integer</code> (vormals <code>Int</code>) typisiert sind.</li>\n</ul>"}], "trans": [{"from": "FIG-af9f248e4e243a6e", "to": "FIG-06419ad8b951020e", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-06419ad8b951020e", "to": "FIG-cc08576c327ea3d9", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Attribut <code>IntegerLiteral.value</code>: Typ von <code>Int</code> zu <code>Integer</code> geändert.</li>\n<li>Attributdefinitionen in Literal-Klassen (<code>IntegerLiteral</code>, <code>RealLiteral</code>, <code>BooleanLiteral</code>, <code>CharLiteral</code>, <code>StringLiteral</code>, <code>OpaqueLiteral</code>): Schreibweise des Typtrenners von <code>: Typ</code> auf <code>:Typ</code> bzw. Vereinheitlichung der Abstände angepasst.</li>\n</ul>"}]};
